  "semantic_checklist": [
    {
      "id": "C01",
      "status": "pass",
      "source_evidence": "Attached raw PDF page 28, printed page 6, Section 1.3 describes dimensional splitting; page 29 completes its limitation. Page 27 supplies the finite volume context.",
      "translation_evidence": "The supplied translation describes a direction-indexed schedule and its sequential execution.",
      "reasoning": "The selected passage and necessary surrounding context are identifiable from the authoritative page renderings. The supplied source hash is recorded without claiming independent recomputation."
    },
    {
      "id": "C02",
      "status": "fail",
      "source_evidence": "Section 1.3 concerns multidimensional hyperbolic problems and extension of one-dimensional high-resolution methods on finite volume grids.",
      "translation_evidence": "States have type Cell → Value for arbitrary Value; D012 and D022 describe arbitrary total constant-preserving update functions.",
      "reasoning": "The translated types do not require a hyperbolic problem, a numerical method for it, or directional one-dimensional solves. Nonempty Direction also permits a single direction."
    },
    {
      "id": "C03",
      "status": "pass",
      "source_evidence": "The selected paragraph describes successive coordinate-direction solves without explicit formal quantifiers or a prescribed directional order.",
      "translation_evidence": "The schedule, final state, and trace depend on the supplied grid, method, and initial state; a schedule entry is supplied for every direction.",
      "reasoning": "These witness dependencies appropriately express a sequential construction from supplied inputs. The substantive discrepancies concern the meanings and restrictions of those inputs, rather than quantifier order."
    },
    {
      "id": "C04",
      "status": "fail",
      "source_evidence": "The explicit geometric condition is rectangular or logically rectangular; the paragraph specifies no fraction bounds or constant-preservation axiom.",
      "translation_evidence": "The translation requires a global coordinate bijection, measurable half-open boxes, fractions in (0,1], and constant preservation for every real parameter.",
      "reasoning": "These introduce substantial additional structural conditions while omitting the inherited hyperbolic and high-resolution method requirements. The supplied source does not establish these as equivalent hypotheses."
    },
    {
      "id": "C05",
      "status": "fail",
      "source_evidence": "Dimensional splitting extends one-dimensional high-resolution methods by successive one-dimensional coordinate solves; effectiveness is qualified and some problems require a more fully multidimensional method.",
      "translation_evidence": "The conclusions establish a mapped schedule, direction coverage, an execution trace, and its length.",
      "reasoning": "The translation captures scheduling but does not establish that the updates solve the relevant directional problems or extend the stated numerical methods. The practical assessment and limitation are also absent."
    },
    {
      "id": "C06",
      "status": "pass",
      "source_evidence": "The source gives descriptive meanings for finite volume methods and dimensional splitting.",
      "translation_evidence": "D001–D087 supply explicit dependency meanings, including arbitrary update maps, coordinate equivalences, list mapping, and the inductive execution relation.",
      "reasoning": "The supplied ledger permits interpretation of the translated operators without relying on their names. In particular, a field labeled as a one-dimensional solve has only the stated constant-preserving function semantics. This check does not assert source equivalence or independent inspection of Lean."
    },
    {
      "id": "C07",
      "status": "fail",
      "source_evidence": "The source makes an introductory algorithmic claim about extension of numerical methods, with qualified practical adequacy.",
      "translation_evidence": "The proposition asserts exact schedule equality and existence of finite iteration traces for supplied total maps.",
      "reasoning": "These exact bookkeeping conclusions do not express the same substantive claim. They also do not assert an exact factorization of multidimensional PDE evolution, so that particular prohibited substitution is absent."
    },
    {
      "id": "C08",
      "status": "fail",
      "source_evidence": "Section 1.2 identifies numerical data as cell averages updated through fluxes; Section 1.3 describes solving coordinate-direction problems.",
      "translation_evidence": "D011 supplies arbitrary cell-value functions, D047 supplies no measure, and D012 supplies updates without an equation or flux relation.",
      "reasoning": "The translated states and updates lack the source roles of finite volume data and directional numerical solves."
    },
    {
      "id": "C09",
      "status": "fail",
      "source_evidence": "The selected description specifies each coordinate direction and successive solution, but no fraction bounds, repetition count, or substep durations.",
      "translation_evidence": "D014 and D056 enforce exactly one step per direction; each prescribed fraction lies in (0,1]. The trace has n+1 states.",
      "reasoning": "Direction coverage and the trace count are consistent with one sequential sweep, but the fraction bounds and exactly-once schedule select additional details not supplied by the passage."
    },
    {
      "id": "C10",
      "status": "unclear",
      "source_evidence": "The source includes logically rectangular grids without defining that term on the supplied pages.",
      "translation_evidence": "D025 and D032 allow any bijection with real coordinate tuples, without continuity, measurability of the map, or other geometric regularity.",
      "reasoning": "The evidence does not establish whether this set-theoretic coordinate model faithfully covers logical rectangularity or admits inappropriate geometries. This geometric issue requires adjudication; the separate algorithmic mismatch is already established."
    },
    {
      "id": "C11",
      "status": "fail",
      "source_evidence": "The discussion addresses more than one spatial dimension and explicitly acknowledges cases needing a more fully multidimensional method.",
      "translation_evidence": "The direction list need only be nonempty, and execution exists for every admissible total operator family without an applicability distinction.",
      "reasoning": "The translation includes the single-direction case and does not represent the source's practical exceptions. Trace existence alone supplies no account of those exceptions."
    },
    {
      "id": "C12",
      "status": "fail",
      "source_evidence": "The source concerns substantive directional solution procedures for multidimensional numerical problems.",
      "translation_evidence": "The translation explicitly states that its result is finite iteration of already supplied total functions; identity updates satisfy constant preservation.",
      "reasoning": "The premises are satisfiable, but the conclusion holds for a generic list of functions regardless of whether those functions solve any directional problem. Thus the intended numerical content is bypassed, rather than the theorem being blocked by impossible premises."
    },
    {
      "id": "N01",
      "status": "fail",
      "source_evidence": "The defining procedure solves one-dimensional problems along each coordinate direction in succession.",
      "translation_evidence": "D010 and D024 implement sequential application, but D012 imposes no directional locality, governing equation, consistency, or numerical-solver requirement.",
      "reasoning": "Sequential execution is represented correctly, but its connection to the source's actual directional solution process is missing."
    },
    {
      "id": "N02",
      "status": "not-applicable",
      "source_evidence": "The selected passage states no norm, metric, or componentwise bound.",
      "translation_evidence": "The translated conclusion contains no norm or metric.",
      "reasoning": "There is no norm or metric convention to compare."
    },
    {
      "id": "N03",
      "status": "not-applicable",
      "source_evidence": "The passage gives no formal error estimate or stability criterion.",
      "translation_evidence": "The translation asserts no error or stability bound.",
      "reasoning": "No technical error or stability notion is substituted; the missing numerical-method linkage is assessed separately."
    },
    {
      "id": "N04",
      "status": "fail",
      "source_evidence": "The inherited finite volume setting approximates solution cell averages and updates them using numerical fluxes.",
      "translation_evidence": "States are arbitrary assignments, and updates need not approximate any solution or flux-based evolution.",
      "reasoning": "Although there is no false equality with exact PDE evolution, the source role of the iterated values as numerical approximations is not retained."
    },
    {
      "id": "N05",
      "status": "not-applicable",
      "source_evidence": "The selected paragraph provides no asymptotic formula, remainder, limiting regime, or accuracy order.",
      "translation_evidence": "The translation contains only finite execution and exact list properties.",
      "reasoning": "There are no asymptotic terms or regimes to compare."
    },
    {
      "id": "N06",
      "status": "fail",
      "source_evidence": "The source describes directional problems being solved within a numerical method.",
      "translation_evidence": "Every update is supplied as a total function on every state and real parameter, and the theorem establishes existence of its finite execution trace.",
      "reasoning": "Totality is assumed for abstract functions without connecting it to solvability or admissibility of the source's directional problems. Trace existence consequently does not express existence of the required numerical solves."
    }
  ],
  "implications": {
    "translation_implies_source": {
      "verdict": "no",
      "reasoning": "The translated proposition guarantees only that prescribed total constant-preserving maps can be executed in a finite direction-indexed order. For example, identity maps yield all asserted schedule and trace properties without any governing hyperbolic equation or directional solution procedure. The translation therefore does not establish the defining numerical content of the selected source claim, even within a rectangular grid setting."
    },
    "source_implies_translation": {
      "verdict": "no",
      "reasoning": "The source describes successive directional solves for numerical methods in its stated setting. It does not assert the translated universal result for arbitrary Value types and arbitrary constant-preserving maps, nor prescribe exactly one occurrence of each direction, fractions in (0,1], or totality and constant preservation for every real parameter. The abstract iteration result may be independently valid, but it is not the proposition expressed by the selected source passage."
    }
  },
  "classification": "not-faithful-different",
  "accepted": false,
  "requires_adjudication": true,
  "findings": [
    {
      "severity": "critical",
      "category": "missing-directional-solver-semantics",
      "source_evidence": "Section 1.3 defines splitting through successive solution of one-dimensional coordinate-direction problems when extending high-resolution methods.",
      "translation_evidence": "D012 and D022 require only total constant-preserving state maps; the translation expressly identifies the absence of equations, directional locality, consistency, conservation, stability, and accuracy.",
      "impact": "The proposition proves generic sequential execution without ensuring that any step performs the source's defining operation."
    },
    {
      "severity": "major",
      "category": "missing-finite-volume-state-role",
      "source_evidence": "Section 1.2 defines cell averages through cell integrals and volumes and describes flux-based updates.",
      "translation_evidence": "D011 supplies arbitrary Cell → Value states; the measurable-space structure supplies neither a measure nor cell averages.",
      "impact": "The states and transitions are not semantically connected to the inherited finite volume problem."
    },
    {
      "severity": "major",
      "category": "unsupported-method-restrictions",
      "source_evidence": "The selected description leaves the detailed fractional-step schedule and substep durations unspecified.",
      "translation_evidence": "The schedule uses each direction exactly once, imposes fractions in (0,1], and assumes constant preservation at every real parameter.",
      "impact": "These are additional implementation and operator restrictions, not source-established equivalences or genuine nonvacuous strengthening of the selected claim."
    },
    {
      "severity": "major",
      "category": "unresolved-logical-rectangularity",
      "source_evidence": "Section 1.3 includes logically rectangular grids without a local formal definition.",
      "translation_evidence": "The coordinate geometry permits arbitrary bijections with real coordinate tuples and imposes no regularity on those bijections.",
      "impact": "Geometric coverage remains unresolved and triggers adjudication independently of the established algorithmic mismatch."
    },
    {
      "severity": "minor",
      "category": "omitted-practical-qualifications",
      "source_evidence": "The source qualifies practical effectiveness and notes that some cases require a more fully multidimensional method.",
      "translation_evidence": "The conclusions concern only schedule construction and trace existence.",
      "impact": "The practical qualifications are not represented. The translation also supplies no universal accuracy or sufficiency guarantee, so this omission should not be mistaken for an explicit contrary guarantee."
    }
  ],
  "rationale": "The attached source pages describe dimensional splitting as a numerical solution procedure. The translation faithfully captures a sequential scheduling pattern, but its dependency ledger shows that the scheduled operations need not solve directional problems at all. This is a substantive change of mathematical content, rather than an equivalent reformulation or a stronger numerical result. Both implication judgments fail on that established mismatch and the additional unsupported scope and restrictions. Adjudication is requested for the separately unresolved interpretation of logical rectangularity."
}
